        "instruction": "在酱汁碗中加入1勺淀粉。",
        "duration": null,
        "heat": null,
        "timerRequired": false,
        "ingredientsUsed": [],
        "gameAction": "add",
        "safetyNote": "",
        "image": "assets/dishes/sources/cn-007-tangcu-liji/step-12.jpeg",
