    "sourceLimitations": [
      "上游标题为韭菜炒蛋，与本记录韭菜炒鸡蛋同菜，保留本记录名称。",
      "原文一份供1人食用，展示原料采用1份用量，原文总量按份数倍增的规则完整保留。",
      "原文从备菜到盛盘大约10分钟，总用时10分钟为约值。",
      "原文总量列食用油10毫升乘份数，操作第4步未量化首次加油、第6步另写再加5毫升，两次加油与总量关系未明确，不推算首次用量或另加后的总量。",
      "清洗韭菜所用水原文未注明用量，不补造定量。"
    ],
