        "instruction": "放入微波炉，高火，6 分钟，煮饭途中准备原料，切好腊肠，洗好青菜，切好红萝卜片，切好葱花，青菜碗 中放入青菜、红萝卜片，倒入 10 ml 油，放入 5 g 盐，小碗 中倒入 10 ml 生抽、5 ml 油。",
