          "markdown": "\n每次制作前需要确定计划做几份。一份正好够 1 个人食用\n\n每份：\n\n* 肉丁/肉末 150g\n* 如果 *面条* 选择了*挂面*：150g  \n  如果 *面条* 选择了*普通面条*：250g\n* 葱 15g\n* 菜码 总量 35g\n* 食用油 10g\n* 豆瓣酱 20g\n* 甜面酱 20g\n\n",
