          "title": "计算",
          "markdown": "\n葱油酱汁可以一次制作多份的量，分次使用。以下提供制作葱油酱汁的基础量，以及每份面条所需的葱油酱汁量。\n\n葱油酱汁基础量 （约够 3-4 份使用）：\n\n- 小葱 100 g\n- 食用油 100 ml\n- 生抽 60 ml\n- 老抽 20 ml\n- 白糖 15 g\n\n每份面条：\n\n- 干面条 80 g （约相当于 150 g 湿面条）\n- 葱油酱汁 15 ml\n\n",
