      "原文酱汁基础量标称约够3—4份，另列每份面条用酱汁15毫升；基础量与每份用量的关系不清，不自行换算或改写基础量为单份。",
      "食材清单同时保留整批酱汁基础量及每份面条量，15毫升葱油酱汁来自前述自制酱汁，不需另购或全部一次拌入。",
      "原介绍一般20分钟完成，但操作另列炸葱15—20分钟、调酱约1分钟及煮面通常3—8分钟，存在原文估计不一致，总用时20分钟保留原介绍，不自行相加。",
