      "枸杞可选，按来源5—6克；浸泡银耳、莲子、红枣及清洗枸杞的水未量化，另有熬煮用水600毫升。",
      "原分段浸泡、熬煮及搅拌时长可能使实际总时长超过简介约3.5小时，保留各原参数，不自行改算总用时。"
